// Normaliza el payload MQTT al mismo formato que HTTP
// para reutilizar el mismo flujo de validación
msg.req = { headers: { 'x-api-key': env.get('BIBLIOTECA_API_KEY') } };
msg.res = null; // No hay respuesta HTTP en MQTT
msg._mqtt = true;
return msg;

// -------------------------------------------------------
// Seguridad: Verifica el header x-api-key contra
// la variable de entorno BIBLIOTECA_API_KEY
// NUNCA hardcodear la API key en el flujo
// -------------------------------------------------------
const expectedKey = env.get('BIBLIOTECA_API_KEY');
const receivedKey = (msg.req && msg.req.headers)
    ? msg.req.headers['x-api-key']
    : null;

if (!expectedKey) {
    node.error('BIBLIOTECA_API_KEY no configurada en variables de entorno');
    msg.payload = { ok: false, error: 'Configuración del servidor incompleta' };
    msg.statusCode = 500;
    return [null, msg];
}

if (receivedKey !== expectedKey) {
    node.warn(`API Key inválida desde ${msg.req && msg.req.ip}`);
    msg.payload = { ok: false, error: 'No autorizado' };
    msg.statusCode = 401;
    return [null, msg];
}

// Extraer el payload real
msg.scanData = (typeof msg.payload === 'string')
    ? JSON.parse(msg.payload)
    : msg.payload;

return [msg, null];

// -------------------------------------------------------
// Determina si el escaneo es:
// - rfid: identificación de usuario
// - qr: identificación de libro
// - prestamo: acción completa (rfid + qr juntos)
// - devolucion: devolución de libro
// -------------------------------------------------------
const scan = msg.scanData || {};

// Validación básica de estructura
if (!scan.tipo) {
    msg.payload = { ok: false, error: 'Payload inválido: falta campo tipo' };
    msg.statusCode = 400;
    return [null, null, null, msg];
}

msg.origen = scan.origen || 'desconocido'; // 'rfid', 'qr', 'api'

switch (scan.tipo) {
    case 'identificar_usuario':
        msg.rfid_tag = scan.rfid_tag;
        return [msg, null, null, null];
    case 'prestamo':
        msg.rfid_tag = scan.rfid_tag;
        msg.qr_codigo = scan.qr_codigo;
        return [null, msg, null, null];
    case 'devolucion':
        msg.rfid_tag = scan.rfid_tag;
        msg.qr_codigo = scan.qr_codigo;
        return [null, null, msg, null];
    default:
        msg.payload = { ok: false, error: `Tipo desconocido: ${scan.tipo}` };
        msg.statusCode = 400;
        return [null, null, null, msg];
}

// Validación del tag RFID
const tag = msg.rfid_tag;

if (!tag || typeof tag !== 'string' || tag.trim() === '') {
    msg.payload = { ok: false, error: 'Tag RFID no válido o vacío' };
    msg.statusCode = 400;
    return [null, msg];
}

// Sanitizar: solo alfanumérico (formato UID RFID)
if (!/^[A-Fa-f0-9]{4,16}$/.test(tag.trim())) {
    msg.payload = { ok: false, error: 'Formato de tag RFID inválido' };
    msg.statusCode = 422;
    return [null, msg];
}

msg.topic = `SELECT id, nombre, apellido, email, tipo_usuario, activo,
    max_prestamos, fecha_vigencia,
    (SELECT COUNT(*) FROM prestamos
     WHERE usuario_id = u.id AND estado = 'activo') AS prestamos_actuales
FROM usuarios u
WHERE rfid_tag = ?`;

msg.params = [tag.trim().toUpperCase()];
return [msg, null];

const rows = msg.payload;

// Usuario no encontrado
if (!rows || rows.length === 0) {
    // Log de intento fallido
    node.warn(`RFID no registrado: ${msg.rfid_tag}`);
    msg.payload = {
        ok: false,
        error: 'TAG_NO_REGISTRADO',
        mensaje: 'Tag RFID no encontrado en el sistema',
        rfid_tag: msg.rfid_tag
    };
    msg.statusCode = 404;
    msg.uiEvent = { tipo: 'error', codigo: 'TAG_NO_REGISTRADO', rfid: msg.rfid_tag };
    return [msg, null];
}

const usuario = rows[0];

// Usuario inactivo
if (!usuario.activo) {
    msg.payload = {
        ok: false,
        error: 'USUARIO_INACTIVO',
        mensaje: `El usuario ${usuario.nombre} ${usuario.apellido} está inactivo`,
        usuario: { id: usuario.id, nombre: `${usuario.nombre} ${usuario.apellido}` }
    };
    msg.statusCode = 403;
    msg.uiEvent = { tipo: 'error', codigo: 'USUARIO_INACTIVO' };
    return [msg, null];
}

// Verificar vigencia
if (usuario.fecha_vigencia) {
    const vigencia = new Date(usuario.fecha_vigencia);
    if (vigencia < new Date()) {
        msg.payload = {
            ok: false,
            error: 'MEMBRESIA_VENCIDA',
            mensaje: `La membresía de ${usuario.nombre} venció el ${usuario.fecha_vigencia}`,
            usuario: { id: usuario.id, nombre: `${usuario.nombre} ${usuario.apellido}` }
        };
        msg.statusCode = 403;
        msg.uiEvent = { tipo: 'error', codigo: 'MEMBRESIA_VENCIDA' };
        return [msg, null];
    }
}

// Éxito
msg.usuario = usuario;
msg.payload = {
    ok: true,
    usuario: {
        id: usuario.id,
        nombre: `${usuario.nombre} ${usuario.apellido}`,
        email: usuario.email,
        tipo: usuario.tipo_usuario,
        prestamos_actuales: usuario.prestamos_actuales,
        max_prestamos: usuario.max_prestamos,
        cupo_disponible: usuario.max_prestamos - usuario.prestamos_actuales
    }
};
msg.statusCode = 200;
msg.uiEvent = { tipo: 'usuario_identificado', usuario: msg.payload.usuario };
return [null, msg];

// -------------------------------------------------------
// Validar que lleguen tanto RFID como QR
// -------------------------------------------------------
const { rfid_tag, qr_codigo } = msg;

if (!rfid_tag || !qr_codigo) {
    msg.payload = {
        ok: false,
        error: 'DATOS_INCOMPLETOS',
        mensaje: 'Se requiere rfid_tag y qr_codigo para realizar un préstamo'
    };
    msg.statusCode = 400;
    return [null, msg];
}

// Formato RFID
if (!/^[A-Fa-f0-9]{4,16}$/.test(rfid_tag.trim())) {
    msg.payload = { ok: false, error: 'RFID_INVALIDO', mensaje: 'Formato de RFID inválido' };
    msg.statusCode = 422;
    return [null, msg];
}

// Formato QR (LIB-XXXXX)
if (!/^LIB-\d{5}$/.test(qr_codigo.trim())) {
    msg.payload = { ok: false, error: 'QR_INVALIDO', mensaje: 'Formato de código QR inválido' };
    msg.statusCode = 422;
    return [null, msg];
}

// Consulta compleja: usuario + ejemplar disponible en una sola query
msg.topic = `
SELECT
    u.id AS usuario_id,
    u.nombre || ' ' || u.apellido AS usuario_nombre,
    u.activo AS usuario_activo,
    u.fecha_vigencia,
    u.max_prestamos,
    (SELECT COUNT(*) FROM prestamos
     WHERE usuario_id = u.id AND estado = 'activo') AS prestamos_actuales,
    l.id AS libro_id,
    l.titulo,
    l.autor,
    l.qr_codigo,
    e.id AS ejemplar_id,
    e.estado AS ejemplar_estado
FROM usuarios u, libros l
LEFT JOIN ejemplares e ON e.libro_id = l.id AND e.estado = 'disponible'
WHERE u.rfid_tag = ? AND l.qr_codigo = ?
LIMIT 1`;
msg.params = [rfid_tag.trim().toUpperCase(), qr_codigo.trim()];
msg.rfid_tag = rfid_tag.trim().toUpperCase();
msg.qr_codigo = qr_codigo.trim();
return [msg, null];

const rows = msg.payload;

// --- Usuario no encontrado ---
if (!rows || rows.length === 0) {
    msg.payload = { ok: false, error: 'TAG_NO_REGISTRADO', mensaje: 'RFID no encontrado' };
    msg.statusCode = 404;
    msg.uiEvent = { tipo: 'error', codigo: 'TAG_NO_REGISTRADO' };
    return [null, msg];
}

const data = rows[0];

// --- Libro no encontrado ---
if (!data.libro_id) {
    msg.payload = { ok: false, error: 'LIBRO_NO_ENCONTRADO', mensaje: `QR ${msg.qr_codigo} no existe` };
    msg.statusCode = 404;
    msg.uiEvent = { tipo: 'error', codigo: 'LIBRO_NO_ENCONTRADO' };
    return [null, msg];
}

// --- Usuario inactivo ---
if (!data.usuario_activo) {
    msg.payload = { ok: false, error: 'USUARIO_INACTIVO', mensaje: 'Usuario inactivo' };
    msg.statusCode = 403;
    msg.uiEvent = { tipo: 'error', codigo: 'USUARIO_INACTIVO' };
    return [null, msg];
}

// --- Vigencia vencida ---
if (data.fecha_vigencia && new Date(data.fecha_vigencia) < new Date()) {
    msg.payload = { ok: false, error: 'MEMBRESIA_VENCIDA', mensaje: 'Membresía vencida' };
    msg.statusCode = 403;
    msg.uiEvent = { tipo: 'error', codigo: 'MEMBRESIA_VENCIDA' };
    return [null, msg];
}

// --- Cupo agotado ---
if (data.prestamos_actuales >= data.max_prestamos) {
    msg.payload = {
        ok: false,
        error: 'CUPO_AGOTADO',
        mensaje: `${data.usuario_nombre} ya tiene ${data.prestamos_actuales}/${data.max_prestamos} préstamos activos`
    };
    msg.statusCode = 409;
    msg.uiEvent = { tipo: 'error', codigo: 'CUPO_AGOTADO' };
    return [null, msg];
}

// --- Ejemplar no disponible ---
if (data.ejemplar_estado !== 'disponible' || !data.ejemplar_id) {
    msg.payload = {
        ok: false,
        error: 'SIN_EJEMPLARES',
        mensaje: `"${data.titulo}" no tiene ejemplares disponibles en este momento`
    };
    msg.statusCode = 409;
    msg.uiEvent = { tipo: 'error', codigo: 'SIN_EJEMPLARES', libro: data.titulo };
    return [null, msg];
}

// --- ✅ Todo válido: preparar transacción ---
msg.prestamo_data = data;

// Fecha devolución: 14 días para estudiantes, 30 para docentes
// (simplificado; se podría parametrizar por tipo_usuario)
const diasPrestamo = 14;
const devolucion = new Date();
devolucion.setDate(devolucion.getDate() + diasPrestamo);
msg.fecha_devolucion = devolucion.toISOString().replace('T', ' ').substring(0, 19);

// Transacción SQLite: actualizar ejemplar + insertar préstamo
msg.topic = `BEGIN TRANSACTION;
UPDATE ejemplares SET estado = 'prestado' WHERE id = ${data.ejemplar_id};
INSERT INTO prestamos
    (usuario_id, ejemplar_id, fecha_devolucion_esperada, estado, rfid_prestamo, qr_prestamo)
VALUES
    (${data.usuario_id}, ${data.ejemplar_id}, '${msg.fecha_devolucion}', 'activo',
     '${msg.rfid_tag}', '${msg.qr_codigo}');
INSERT INTO audit_log (tipo, origen, usuario_id, ejemplar_id, mensaje, payload_raw)
VALUES ('prestamo', 'iot', ${data.usuario_id}, ${data.ejemplar_id},
    'Préstamo registrado: ${data.titulo}', '${JSON.stringify(msg.scanData || {})}');
COMMIT;`;

return [msg, null];

const data = msg.prestamo_data;

msg.payload = {
    ok: true,
    accion: 'prestamo',
    mensaje: `Préstamo registrado exitosamente`,
    prestamo: {
        usuario: data.usuario_nombre,
        libro: data.titulo,
        autor: data.autor,
        ejemplar_id: data.ejemplar_id,
        fecha_devolucion_esperada: msg.fecha_devolucion
    }
};
msg.statusCode = 201;
msg.uiEvent = {
    tipo: 'prestamo_exitoso',
    datos: msg.payload.prestamo
};
return msg;

const { rfid_tag, qr_codigo } = msg;

if (!rfid_tag || !qr_codigo) {
    msg.payload = { ok: false, error: 'DATOS_INCOMPLETOS', mensaje: 'Se requiere rfid_tag y qr_codigo' };
    msg.statusCode = 400;
    return [null, msg];
}

// Buscar préstamo activo que coincida con usuario Y libro
msg.topic = `
SELECT
    p.id AS prestamo_id,
    p.ejemplar_id,
    p.fecha_prestamo,
    p.fecha_devolucion_esperada,
    u.nombre || ' ' || u.apellido AS usuario_nombre,
    l.titulo,
    l.autor,
    CASE WHEN p.fecha_devolucion_esperada < datetime('now','localtime') THEN 1 ELSE 0 END AS vencido
FROM prestamos p
JOIN usuarios   u ON p.usuario_id  = u.id
JOIN ejemplares e ON p.ejemplar_id = e.id
JOIN libros     l ON e.libro_id    = l.id
WHERE u.rfid_tag  = ?
  AND l.qr_codigo = ?
  AND p.estado = 'activo'
LIMIT 1`;
msg.params = [rfid_tag.trim().toUpperCase(), qr_codigo.trim()];
msg.rfid_tag  = rfid_tag.trim().toUpperCase();
msg.qr_codigo = qr_codigo.trim();
return [msg, null];

const rows = msg.payload;

if (!rows || rows.length === 0) {
    msg.payload = {
        ok: false,
        error: 'PRESTAMO_NO_ENCONTRADO',
        mensaje: 'No se encontró un préstamo activo para este usuario y libro'
    };
    msg.statusCode = 404;
    msg.uiEvent = { tipo: 'error', codigo: 'PRESTAMO_NO_ENCONTRADO' };
    return [null, msg];
}

const prestamo = rows[0];
msg.prestamo_data = prestamo;

const ahora = new Date().toISOString().replace('T', ' ').substring(0, 19);

// Transacción: actualizar préstamo + liberar ejemplar
msg.topic = `BEGIN TRANSACTION;
UPDATE prestamos
    SET estado = 'devuelto',
        fecha_devolucion_real = '${ahora}',
        rfid_devolucion = '${msg.rfid_tag}'
    WHERE id = ${prestamo.prestamo_id};
UPDATE ejemplares
    SET estado = 'disponible'
    WHERE id = ${prestamo.ejemplar_id};
INSERT INTO audit_log (tipo, origen, mensaje, payload_raw)
    VALUES ('devolucion', 'iot',
        'Devolución registrada: ${prestamo.titulo} por ${prestamo.usuario_nombre}',
        '${JSON.stringify({ prestamo_id: prestamo.prestamo_id })}');
COMMIT;`;

return [msg, null];

const prestamo = msg.prestamo_data;
const ahora = new Date().toISOString().replace('T', ' ').substring(0, 19);

msg.payload = {
    ok: true,
    accion: 'devolucion',
    vencido: prestamo.vencido === 1,
    mensaje: prestamo.vencido
        ? `Devolución tardía de "${prestamo.titulo}" (venció el ${prestamo.fecha_devolucion_esperada})`
        : `"${prestamo.titulo}" devuelto correctamente`,
    devolucion: {
        usuario: prestamo.usuario_nombre,
        libro: prestamo.titulo,
        autor: prestamo.autor,
        fecha_devolucion_real: ahora,
        fecha_devolucion_esperada: prestamo.fecha_devolucion_esperada,
        dias_retraso: prestamo.vencido
            ? Math.ceil((new Date() - new Date(prestamo.fecha_devolucion_esperada)) / 86400000)
            : 0
    }
};
msg.statusCode = 200;
msg.uiEvent = {
    tipo: prestamo.vencido ? 'devolucion_tardía' : 'devolucion_exitosa',
    datos: msg.payload.devolucion
};
return msg;

msg.topic = `SELECT * FROM estadisticas_dashboard;
SELECT * FROM prestamos_activos ORDER BY vencido DESC, fecha_devolucion_esperada ASC LIMIT 20;`;
return msg;

// La consulta múltiple devuelve array de resultados
const results = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
msg.payload = {
    ok: true,
    timestamp: new Date().toISOString(),
    estadisticas: results[0] && results[0][0] ? results[0][0] : {},
    prestamos_activos: results[1] || []
};
msg.statusCode = 200;
return msg;

// Solo log en desarrollo; en producción usar nodo debug con nivel 'warning'
if (env.get('NODE_ENV') !== 'production') {
    node.log(`[AUDIT] ${msg.payload && msg.payload.accion || 'evento'}: ${JSON.stringify(msg.payload)}`);
}
return null; // No propagar

const d = msg.payload;
msg.topic = `INSERT INTO usuarios (nombre, apellido, email, rfid_tag, tipo_usuario, max_prestamos, fecha_vigencia, activo) VALUES ('${d.nombre}', '${d.apellido}', '${d.email}', '${d.rfid_tag}', '${d.tipo_usuario}', ${d.max_prestamos}, ${d.fecha_vigencia ? `'${d.fecha_vigencia}'` : 'NULL'}, 1);`;
return msg;

const d = msg.payload;
msg.topic = `
BEGIN TRANSACTION;
INSERT INTO libros (titulo, autor, isbn, editorial, anio, qr_codigo) 
VALUES ('${d.titulo}', '${d.autor}', '${d.isbn}', '${d.editorial}', ${d.anio || 'NULL'}, '${d.qr_codigo}');
INSERT INTO ejemplares (libro_id, estado) 
VALUES (last_insert_rowid(), 'disponible');
COMMIT;
`;
return msg;

msg.payload = { ok: true };
msg.statusCode = 201;
return msg;

// -------------------------------------------------------
// Genera comando shell para copiar el .db de SQLite
// Utiliza el comando VACUUM INTO de SQLite para un
// respaldo consistente (no requiere bloquear la BD)
// -------------------------------------------------------
const tipo = msg.payload.tipo || 'manual';
const ahora = new Date();
const timestamp = ahora.toISOString()
    .replace(/[:.]/g, '-')
    .replace('T', '_')
    .substring(0, 19);

const DB_PATH     = env.get('SQLITE_DB_PATH') || '/data/biblioteca/biblioteca.db';
const BACKUP_DIR  = env.get('BACKUP_DIR')     || '/data/backups';
const MAX_BACKUPS = parseInt(env.get('MAX_BACKUPS') || '30');

const backupFile = `${BACKUP_DIR}/biblioteca_${tipo}_${timestamp}.db`;

// Comando:
// 1. Crear directorio si no existe
// 2. Copiar con sqlite3 VACUUM INTO (respaldo limpio y consistente)
// 3. Comprimir con gzip
// 4. Limpiar backups antiguos (>MAX_BACKUPS archivos)
msg.payload = [
    `mkdir -p ${BACKUP_DIR}`,
    `sqlite3 ${DB_PATH} ".timeout 5000" ".backup ${backupFile}"`,
    `gzip -9 ${backupFile}`,
    `ls -t ${BACKUP_DIR}/biblioteca_*.db.gz | tail -n +${MAX_BACKUPS + 1} | xargs -r rm --`
].join(' && ');

msg.backup_meta = { tipo, timestamp, archivo: backupFile + '.gz' };
node.log(`Iniciando backup ${tipo}: ${backupFile}.gz`);
return msg;

const stdout = msg.payload || '';
const meta = msg.backup_meta || {};

msg.topic = `INSERT INTO audit_log (tipo, origen, mensaje)
    VALUES ('backup', 'sistema', 'Respaldo ${meta.tipo || ''} completado: ${meta.archivo || ''}');`;

node.status({ fill: 'green', shape: 'dot', text: `OK ${meta.timestamp}` });
node.log(`Backup completado: ${meta.archivo}`);
return msg;

const err = msg.payload || 'Error desconocido';
node.error(`Error en backup: ${err}`);
node.status({ fill: 'red', shape: 'ring', text: 'ERROR backup' });

msg.topic = `INSERT INTO audit_log (tipo, origen, mensaje)
    VALUES ('backup', 'sistema', 'ERROR en respaldo: ${String(err).replace(/'/g, "''")}');`;
return msg;
